<script>import {onMount} from 'svelte';import {ArrowLeft,Sparkles} from 'lucide-svelte';let quotes=[];let current=0;onMount(async()=>{const r=await fetch('/data/famous-quotes.json');const d=await r.json();quotes=Array.isArray(d)?d:(d.quotes||[]);});$: item=quotes[current];function next(){if(quotes.length)current=(current+1)%quotes.length;}</script><svelte:head><title>学習のヒント — MANABIXX</title></svelte:head><main><a href="/" class="back"><ArrowLeft size={17}/> MANABIXXホーム</a><div class="eyebrow"><Sparkles size={14}/> DAILY INSPIRATION</div><h1>今日のひとこと</h1>{#if item}<section><div class="quote">“</div><blockquote>{item.text||item.quote||item.content||JSON.stringify(item)}</blockquote><p>{item.author||'学習のヒント'}</p><button onclick={next}>別の言葉を見る <Sparkles size={16}/></button></section><small>{current+1} / {quotes.length}</small>{:else}<p>メッセージを読み込んでいます…</p>{/if}</main><style>main{max-width:800px;margin:auto;padding:45px 22px;color:var(--ink)}.back{display:inline-flex;gap:8px;color:var(--muted)}.eyebrow{display:flex;gap:8px;align-items:center;color:var(--brand);font-size:11px;font-weight:800;letter-spacing:.15em;margin-top:75px}h1{font-size:42px}section{margin:35px 0;padding:45px;background:var(--surface);border:1px solid var(--line);border-radius:24px;text-align:center;box-shadow:var(--shadow)}.quote{font-size:70px;color:var(--brand);height:55px}blockquote{font-size:clamp(21px,4vw,30px);line-height:1.8;font-weight:700;margin:15px 0 25px}section p{color:var(--muted)}button{margin-top:20px;padding:13px 18px;border:0;border-radius:12px;background:var(--brand);color:white;font-weight:700;display:inline-flex;gap:8px;align-items:center}main>small{color:var(--muted)}</style>